function isMissingName(value) {
  const normalized = String(value ?? '').trim().toLowerCase();

  return (
    !normalized ||
    normalized === 'unknown' ||
    normalized === 'not provided' ||
    normalized === 'not specified'
  );
}

function normalizeTime(value) {
  const raw = String(value || '').trim().toLowerCase().replace(/\s+/g, ' ');
  const hm = raw.match(/\b(\d{1,2})[:.](\d{2})\s*(am|pm)?\b/i);
  if (hm) {
    let hour = Number(hm[1]);
    const minute = Number(hm[2]);
    const meridiem = hm[3] ? hm[3].toLowerCase() : '';
    if (meridiem === 'pm' && hour < 12) hour += 12;
    if (meridiem === 'am' && hour === 12) hour = 0;
    if (hour >= 0 && hour <= 23 && minute >= 0 && minute <= 59) {
      return String(hour).padStart(2, '0') + ':' + String(minute).padStart(2, '0');
    }
  }
  const hOnly = raw.match(/\b(\d{1,2})\s*(am|pm)\b/i);
  if (hOnly) {
    let hour = Number(hOnly[1]);
    const meridiem = hOnly[2].toLowerCase();
    if (meridiem === 'pm' && hour < 12) hour += 12;
    if (meridiem === 'am' && hour === 12) hour = 0;
    if (hour >= 0 && hour <= 23) return String(hour).padStart(2, '0') + ':00';
  }
  return '';
}

function extractName(value) {
  const text = String(value || '').trim();
  if (!text) return '';
  const cleaned = text
    .replace(/^(my name is|name is|i am|i'm|this is)\s+/i, '')
    .replace(/^(book|yes|ok|okay|please|at|for)\b\s*/i, '')
    .trim();
  if (!cleaned || /\d/.test(cleaned) || cleaned.length > 80) return '';
  return cleaned;
}

function looksLikeNewBookingRequest(value, selectedTime) {
  const text = String(value || '').toLowerCase();
  const hasService = /\b(manicure|pedicure|haircut|massage|facial|nails?|gel|маникюр|педикюр|стрижка|массаж)\b/i.test(text);
  const hasDate = /\b(today|tomorrow|monday|tuesday|wednesday|thursday|friday|saturday|sunday|сегодня|завтра)\b/i.test(text) || /\b\d{1,2}[.\/\-]\d{1,2}\b/.test(text) || /\b\d{1,2}\s+(jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec|january|february|march|april|june|july|august|september|october|november|december)\b/i.test(text);
  return Boolean(hasService && hasDate && selectedTime);
}

